\section*{AP \({ }^{\text {® }}\) CALCULUS AB \\ 2007 SCORING GUIDELINES}

\section*{Question 4}

A particle moves along the \(x\)-axis with position at time \(t\) given by \(x(t)=e^{-t} \sin t\) for \(0 \leq t \leq 2 \pi\).
\begin{itemize}
\item[(a)] Find the time \(t\) at which the particle is farthest to the left. Justify your answer.
\item[(b)] Find the value of the constant \(A\) for which \(x(t)\) satisfies the equation \(A x^{\prime \prime}(t)+x^{\prime}(t)+x(t)=0\) for \(0<t<2 \pi\).
\item[(a)]
\[
\begin{aligned}
& x^{\prime}(t)=-e^{-t} \sin t+e^{-t} \cos t=e^{-t}(\cos t-\sin t) \\
& x^{\prime}(t)=0 \text { when } \cos t=\sin t \text {. Therefore, } x^{\prime}(t)=0 \text { on } \\
& 0 \leq t \leq 2 \pi \text { for } t=\frac{\pi}{4} \text { and } t=\frac{5 \pi}{4} .
\end{aligned}
\]
The candidates for the absolute minimum are at \(t=0, \frac{\pi}{4}, \frac{5 \pi}{4}\), and \(2 \pi\).

\begin{tabular}[t]{|l|l|}
\hline \(t\) & \(x(t)\) \\
\hline 0 & \(e^{0} \sin (0)=0\) \\
\hline \(\frac{\pi}{4}\) & \(e^{-\frac{\pi}{4}} \sin \left(\frac{\pi}{4}\right)>0\) \\
\hline \(\frac{5 \pi}{4}\) & \(e^{-\frac{5 \pi}{4}} \sin \left(\frac{5 \pi}{4}\right)<0\) \\
\hline \(2 \pi\) & \(e^{-2 \pi} \sin (2 \pi)=0\) \\
\hline
\end{tabular}
The particle is farthest to the left when \(t=\frac{5 \pi}{4}\).
\end{itemize}
\[
5:\left\{\begin{array}{l}
2: x^{\prime}(t) \\
1: \text { sets } x^{\prime}(t)=0 \\
1: \text { answer } \\
1: \text { justification }
\end{array}\right.
\]
\begin{itemize}
\item[(b)]
\[
\begin{aligned}
x^{\prime \prime}(t) & =-e^{-t}(\cos t-\sin t)+e^{-t}(-\sin t-\cos t) \\
& =-2 e^{-t} \cos t
\end{aligned}
\]
\[
\begin{aligned}
& A x^{\prime \prime}(t)+x^{\prime}(t)+x(t) \\
& \quad=A\left(-2 e^{-t} \cos t\right)+e^{-t}(\cos t-\sin t)+e^{-t} \sin t \\
& \quad=(-2 A+1) e^{-t} \cos t \\
& \quad=0
\end{aligned}
\]
Therefore, \(A=\frac{1}{2}\).
\end{itemize}
\[
4:\left\{\begin{aligned}
2: & x^{\prime \prime}(t) \\
1: & \text { substitutes } x^{\prime \prime}(t), x^{\prime}(t), \text { and } x(t) \\
& \text { into } A x^{\prime \prime}(t)+x^{\prime}(t)+x(t) \\
1: & \text { answer }
\end{aligned}\right.
\]
